def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Tally opponent and own actions
    opp_d = 0
    opp_c = 0
    my_d = 0
    my_c = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        else:
            opp_c += 1
        if a == 'D':
            my_d += 1
        else:
            my_c += 1

    last_me, last_opp = history[-1]

    # Endgame exploitation against a likely pure cooperator
    if n >= 95:
        if opp_d == 0:
            return 'D'
        if opp_d <= 2 and n >= 98:
            return 'D'

    # Against sustained defector: stop cooperating uselessly
    if opp_c == 0:
        return 'D'

    # Pure cooperator early/mid: occasionally exploit, but keep cooperation stable
    if opp_d == 0:
        if n >= 6 and n < 95 and rng.random() < 0.02:
            return 'D'
        return 'C'

    # Detect random-like opponent: roughly half defections
    if n >= 10:
        ratio = opp_d / n
        if 0.38 <= ratio <= 0.62:
            # Against a noisy/random opponent, defecting yields (1+5)/2 > (3+0)/2
            return 'D'

    # Strong recent defection pressure
    recent = history[-10:] if n >= 10 else history
    rec_opp_d = 0
    rec_opp_c = 0
    for a, b in recent:
        if b == 'D':
            rec_opp_d += 1
        else:
            rec_opp_c += 1

    if rec_opp_d >= 7:
        return 'D'

    if rec_opp_d >= 4:
        # Alternate pressure and forgiveness to avoid death spiral
        if last_opp == 'C':
            return 'C'
        # Probe cooperation occasionally even under pressure
        if rng.random() < 0.25:
            return 'C'
        return 'D'

    # Forgiveness pattern to recover from mutual defection
    if last_opp == 'D':
        tail = history[-3:] if n >= 3 else history
        opp_ds = sum(1 for a, b in tail if b == 'D')
        my_ds = sum(1 for a, b in tail if a == 'D')
        if opp_ds >= 2 and my_ds >= 2:
            # Both stuck: try cooperation to reset
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        if opp_ds == 1 and rng.random() < 0.20:
            return 'C'
        return 'D'

    # Opponent cooperated last round. Mostly cooperate.
    # Exploit slightly more near end against imperfect cooperators.
    if n >= 85 and opp_d >= 2:
        if rng.random() < 0.25:
            return 'D'
        return 'C'

    # Avoid being too predictable: rare probe against those with some defections
    if n >= 15 and opp_d >= 1 and rng.random() < 0.03:
        return 'D'

    return 'C'
